#!/usr/bin/env sh
# fetch Connect - Horizons Regional Transport, Connect - Horizons Regional Transport (NZ) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://www.horizons.govt.nz/HRC/media/Data/files/tranzit/HRC_GTFS_Production.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
